Rule.Source:
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AttributeRequest;
import sailpoint.object.ProvisioningPlan.Operation;
import sailpoint.api.IdentityService;

if (plan == null || plan.getAccountRequests() == null) {
    return;
}

for (Iterator it = plan.getAccountRequests().iterator(); it.hasNext();) {
    AccountRequest req = (AccountRequest) it.next();
    if (!application.getName().equals(req.getApplication())) {
        continue;
    }

    if (AccountRequest.Operation.Delete.equals(req.getOperation())) {
        req.setOperation(AccountRequest.Operation.Modify);
        Identity identity = plan.getIdentity();
        if (identity != null) {
            IdentityService svc = new IdentityService(context);
            Link link = svc.getLink(identity, application, null, req.getNativeIdentity());
            if (link != null) {
                List current = fsgovAsList(link.getAttribute("groups"));
                for (Iterator g = current.iterator(); g.hasNext();) {
                    String group = (String) g.next();
                    if (fsgovIsGovernedGroup(context, group)) {
                        req.add(new AttributeRequest("groups", Operation.Remove, group));
                    }
                }
            }
        }
        log.info("fsgov: converted Delete of " + req.getNativeIdentity() + " to removal of governed groups");
    }

    List attrs = req.getAttributeRequests();
    if (attrs == null) {
        continue;
    }
    List removes = new ArrayList();
    List others = new ArrayList();
    for (Iterator a = attrs.iterator(); a.hasNext();) {
        AttributeRequest ar = (AttributeRequest) a.next();
        if ("groups".equals(ar.getName())) {
            List values = fsgovAsList(ar.getValue());
            List kept = new ArrayList();
            for (Iterator v = values.iterator(); v.hasNext();) {
                String value = (String) v.next();
                if (fsgovIsGovernedGroup(context, value)) {
                    kept.add(value);
                } else {
                    log.warn("fsgov: dropped ungoverned group " + value + " for " + req.getNativeIdentity());
                }
            }
            if (kept.isEmpty()) {
                continue;
            }
            ar.setValue(kept.size() == 1 ? (Object) kept.get(0) : (Object) kept);
        }
        if (Operation.Remove.equals(ar.getOperation())) {
            removes.add(ar);
        } else {
            others.add(ar);
        }
    }
    List ordered = new ArrayList(removes);
    ordered.addAll(others);
    req.setAttributeRequests(ordered);
}
